mapper.select:
select * from booknest.`chat_group_invitation`
where group_id = #{groupId}
  and invitee_id = #{inviteeId}
  and type = #{type}
  and status = #{status}
limit 1

mapper.update:
update booknest.`chat_group_invitation`
set status = #{status}, handle_time = #{handleTime}
where id = #{id}
